const input = $input.first().json;
const body = input.body || {};

const featureName = body.feature_name || 'Unknown Feature';
const author = body.author || 'N/A';
const csvData = body.csv_data || '';

// Parse CSV: name,precondition,steps,expected,priority
const lines = csvData.trim().split('\n');
const testCases = [];

for (let i = 0; i < lines.length; i++) {
  const line = lines[i].trim();
  if (!line) continue;

  // Skip header row if present
  if (i === 0 && line.toLowerCase().includes('name')) continue;

  const cols = line.split(',').map(c => c.trim());
  testCases.push({
    name: cols[0] || '',
    precondition: cols[1] || '-',
    steps: cols[2] || '',
    expected: cols[3] || '',
    priority: cols[4] || 'Medium'
  });
}

return [{ json: { feature_name: featureName, author, test_cases: testCases } }];

const input = $input.first().json;
const featureName = input.feature_name;
const author = input.author;
const testCases = input.test_cases || [];

const now = new Date();
const dateStr = now.toISOString().split('T')[0];

const testCaseRows = testCases.map((tc, i) => {
  const id = String(i + 1).padStart(3, '0');
  return `| TC-${id} | ${tc.name} | ${tc.precondition} | ${tc.steps} | ${tc.expected} | ${tc.priority} | - |`;
}).join('\n');

const markdown = `# テスト仕様書: ${featureName}

## 基本情報

| 項目 | 内容 |
|------|------|
| 機能名 | ${featureName} |
| 作成日 | ${dateStr} |
| 作成者 | ${author} |
| テストケース数 | ${testCases.length} |

## テストケース

| ID | テスト名 | 前提条件 | 手順 | 期待結果 | 優先度 | 結果 |
|----|----------|----------|------|----------|--------|------|
${testCaseRows}

## テスト結果サマリ

| 項目 | 件数 |
|------|------|
| 総テストケース数 | ${testCases.length} |
| 成功 | - |
| 失敗 | - |
| 未実施 | ${testCases.length} |
`;

return [{ json: { success: true, feature_name: featureName, total_cases: testCases.length, markdown } }];
